"use strict";
// Actual editor/checklist modules and native CSS, with an isolated Modal/service
// adapter. CDP supplies trusted pointer, keyboard and touch-capability changes.
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),http=require('node:http'),{spawn}=require('node:child_process'),assert=require('node:assert/strict');
async function run(){
 const root=path.resolve(__dirname,'../..'),output=fs.mkdtempSync(path.join(os.tmpdir(),'itacan-step-context-'));
 const native=process.env.HUB_TEST_NATIVE_CSS||path.join(os.tmpdir(),'itacan-native-app.css');
 assert(fs.existsSync(native),'Supply native Obsidian CSS through HUB_TEST_NATIVE_CSS');
 const server=http.createServer((req,res)=>{const name=decodeURIComponent(new URL(req.url,'http://localhost').pathname),file=name==='/lib/tests/native-app.css'?native:path.resolve(root,'.'+name);if(file!==native&&!file.startsWith(root+path.sep)){res.writeHead(403).end();return}try{res.setHeader('Content-Type',file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file))}catch{res.writeHead(404).end()}});
 await new Promise(r=>server.listen(0,'127.0.0.1',r));
 const child=spawn(process.env.HUB_TEST_BROWSER||'C:/Program Files/Google/Chrome/Application/chrome.exe',['--headless=new','--no-first-run','--disable-background-networking','--remote-debugging-port=0','--user-data-dir='+path.join(output,'profile'),'about:blank'],{windowsHide:true,stdio:'ignore'});
 let socket,checks=0;const check=(v,message)=>{assert(v,message);checks++},near=(a,b)=>Math.abs(a-b)<.1;
 const timeout=setTimeout(()=>{child.kill();server.close();console.error('Step browser test timed out');process.exit(1)},60000);
 try{
  let devtools;for(let i=0;i<200;i++){try{devtools=fs.readFileSync(path.join(output,'profile/DevToolsActivePort'),'utf8').split(/\r?\n/);break}catch{await new Promise(r=>setTimeout(r,50))}}
  assert(devtools,'Browser starts');const targets=await(await fetch('http://127.0.0.1:'+devtools[0]+'/json/list')).json();socket=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise((r,j)=>{socket.addEventListener('open',r,{once:true});socket.addEventListener('error',j,{once:true})});
  let sequence=0;const pending=new Map();socket.addEventListener('message',event=>{const m=JSON.parse(event.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result)}});
  const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});socket.send(JSON.stringify({id,method,params}))});
  const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value};
  const move=(x=1,y=1)=>call('Input.dispatchMouseEvent',{type:'mouseMoved',x,y});
  const point=expression=>evaluate(`(()=>{const e=(${expression});e.scrollIntoView({block:'nearest'});const b=e.getBoundingClientRect();return{x:b.x+b.width/2,y:b.y+b.height/2}})()`);
  const hover=async expression=>{const p=await point(expression);await move(p.x,p.y)};
  const click=async expression=>{const p=await point(expression);await move(p.x,p.y);await call('Input.dispatchMouseEvent',{type:'mousePressed',...p,button:'left',clickCount:1});await call('Input.dispatchMouseEvent',{type:'mouseReleased',...p,button:'left',clickCount:1});await evaluate('frames()')};
  const key=async(key,vk,modifiers=0)=>{await call('Input.dispatchKeyEvent',{type:'keyDown',key,code:key,windowsVirtualKeyCode:vk,modifiers,...(key==='Enter'?{text:'\r'}:{})});await call('Input.dispatchKeyEvent',{type:'keyUp',key,windowsVirtualKeyCode:vk,modifiers});await evaluate('frames()')};
  const screenshot=async name=>{const result=await call('Page.captureScreenshot',{format:'png'});fs.writeFileSync(path.join(output,name+'.png'),Buffer.from(result.data,'base64'))};
  await call('Page.enable');await call('Runtime.enable');
  await call('Page.navigate',{url:'http://127.0.0.1:'+server.address().port+'/lib/tests/task-editor-step-context.html'});
  for(let i=0;i<200&&!await evaluate('Boolean(window.testDone)');i++)await new Promise(r=>setTimeout(r,25));await evaluate('testDone');
  const panel=await evaluate('panelGeometry()');
  for(const [width,height,dpr]of [[1024,900,1],[390,720,1.5]]){
   await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:dpr,mobile:false});
   for(const mode of ['Add','Edit'])for(const count of [0,1,5]){
    await evaluate(`openEditor('${mode}',${count},${count===5})`);
    if(!count){const g=await evaluate('geometry()');check(g.hidden&&near(g.checkboxCenter,g.chevronCenter),mode+' empty Add steps aligned');await click('editor.taskFields.checklist.toggle');await evaluate('input(editor.taskFields.steps.draftInput,"New Step");editor.taskFields.steps.commitPending()')}
    else if(mode==='Add')await click('editor.taskFields.checklist.toggle');
    const g=await evaluate('geometry()');check(!g.hidden&&near(g.checkboxCenter,g.guideCenter),mode+' guide at checkbox center');check(near(g.chevronCenter,g.checkboxCenter),mode+' heading centered');check(near(g.guideTop,g.headingBottom)&&near(g.guideBottom,g.addBottom-3),mode+' original vertical extent');check(g.guideWidth==='1px',mode+' original guide thickness');check(near(g.stepX,g.addIcon.x)&&near(g.textX,g.addText.x),mode+' children/Add columns');check(near(g.stepX-g.guideCenter,12),mode+' original guide-to-checkbox spacing');
    await evaluate('editor.taskFields.checklist.toggle.focus()');await move();const before=await evaluate('({row:box(rows()[0]),text:box(rows()[0].querySelector(".hub-task-step-text")),controls:controlState(rows()[0])})');check(before.controls.every(c=>c.opacity==='0'&&c.pointer==='none'),mode+' idle controls hidden/noninteractive');
    const invisible=await evaluate('(()=>{const b=rows()[0].querySelector(".hub-task-step-remove"),r=b.getBoundingClientRect();return document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)!==b&&!b.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))})()');check(invisible,mode+' hidden control excluded from hit testing');
    await hover('rows()[0].querySelector(".hub-task-step-text")');check(await evaluate('controlState(rows()[0]).every(c=>c.opacity==="1"&&c.pointer==="auto")'),mode+' hovered row visible');check(await evaluate('rows().slice(1).every(r=>controlState(r).every(c=>c.opacity==="0"))'),mode+' other rows hidden');
    const after=await evaluate('({row:box(rows()[0]),text:box(rows()[0].querySelector(".hub-task-step-text")),controls:controlState(rows()[0])})');check(JSON.stringify(before.row)===JSON.stringify(after.row)&&JSON.stringify(before.text)===JSON.stringify(after.text)&&JSON.stringify(before.controls.map(c=>c.box))===JSON.stringify(after.controls.map(c=>c.box)),mode+' no hover layout movement');
    check(await evaluate('getComputedStyle(editor.taskFields.steps.add).opacity==="1"'),mode+' permanent Add action');await move();check(await evaluate('controlState(rows()[0]).every(c=>c.opacity==="0")'),mode+' pointer leave hides');
    await evaluate('rows()[0].querySelector("input").focus()');await key('Tab',9);check(await evaluate('document.activeElement===rows()[0].querySelector(".hub-task-step-text")&&controlState(rows()[0]).every(c=>c.opacity==="1")'),mode+' text keyboard focus reveals');if(count>1){await key('Tab',9);check(await evaluate('document.activeElement.classList.contains("hub-task-step-drag-handle")'),mode+' handle tab access');}
    // Focus delete through Tab from the text (a disabled single-step handle is skipped).
    await evaluate('rows()[0].querySelector(".hub-task-step-text").focus()');await key('Tab',9);if(count>1)await key('Tab',9);check(await evaluate('document.activeElement.classList.contains("hub-task-step-remove")&&document.activeElement.matches(":focus-visible")&&getComputedStyle(document.activeElement).outlineStyle!=="none"'),mode+' accessible delete with visible focus');
    if(count>1){await evaluate('rows()[0].querySelector(".hub-task-step-drag-handle").focus()');const id=await evaluate('editor.taskFields.state.steps[0].id');await key('End',35,1);check(await evaluate(`editor.taskFields.state.steps.at(-1).id===${JSON.stringify(id)}`),mode+' keyboard reorder');
     const p=await point('rows()[0].querySelector(".hub-task-step-drag-handle")'),end=await point('rows()[2]');await move(p.x,p.y);await call('Input.dispatchMouseEvent',{type:'mousePressed',...p,button:'left',clickCount:1});await move(p.x+10,end.y);await evaluate('frames()');check(await evaluate('!!document.querySelector(".is-pointer-dragging")&&controlState(document.querySelector(".is-pointer-dragging")).every(c=>c.opacity==="1")'),mode+' dragging keeps controls visible');await call('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x+10,y:end.y,button:'left',clickCount:1});await evaluate('new Promise(r=>setTimeout(r,180))');check(await evaluate('!document.querySelector(".is-pointer-dragging,.hub-task-step-placeholder")'),mode+' drop feedback cleaned');
     await evaluate('editor.taskFields.checklist.toggle.focus()');await move();await screenshot(mode+'-'+width+'-idle');await hover('rows()[1]');await screenshot(mode+'-'+width+'-hover');
    }
    if(count>1){await evaluate('editor.taskFields.checklist.toggle.focus()');const completed='rows().find(r=>r.querySelector("input").checked)';await hover(completed);check(await evaluate(`controlState(${completed}).every(c=>c.opacity==="1")`),mode+' completed row reveals controls');await move();check(await evaluate(`controlState(${completed}).every(c=>c.opacity==="0")`),mode+' completed row hides controls');}
    const stepDraft=await evaluate('JSON.stringify(editor.taskFields.state.steps)');await click('editor.taskFields.checklist.toggle');check(await evaluate('geometry().hidden'),mode+' collapse retained');check(near((await evaluate('geometry()')).chevronCenter,g.checkboxCenter),mode+' collapsed heading alignment');await click('editor.taskFields.checklist.toggle');check(await evaluate('JSON.stringify(editor.taskFields.state.steps)')===stepDraft,mode+' disclosure preserves draft');
    const n=await evaluate('rows().length');await evaluate('rows()[0].querySelector(".hub-task-step-text").focus()');await key('Tab',9);if(n>1)await key('Tab',9);await key('Enter',13);check(await evaluate('rows().length')===n-1,mode+' keyboard deletion works');
    const saved=await evaluate('fingerprint()');await evaluate('editor.close()');check(await evaluate('fingerprint()')===saved,mode+' Cancel isolates draft');
   }
  }
  await call('Emulation.setDeviceMetricsOverride',{width:1024,height:900,deviceScaleFactor:1,mobile:false});check(JSON.stringify(await evaluate('panelGeometry()'))===JSON.stringify(panel),'Tasks panel geometry unchanged');check(await evaluate('legacyComposer()'),'Capture composer retains original hierarchy');
  await evaluate('openEditor("Edit",3)');await click('rows()[1].querySelector("input")');check(await evaluate('!editor.taskFields.state.steps[1].completed'),'Uncomplete step');await click('rows()[1].querySelector("input")');check(await evaluate('editor.taskFields.state.steps[1].completed'),'Complete step');
  await click('rows()[0].querySelector(".hub-task-step-text")');await evaluate('input(document.activeElement,"Edited step")');await key('Enter',13);await click('editor.taskFields.steps.add');await evaluate('input(editor.taskFields.steps.draftInput,"Saved pending step")');await click('editor.contentEl.querySelector(".hub-task-dialog-actions .mod-cta")');check(await evaluate('editor.closed&&writeCount()===1'),'Save succeeds once');await evaluate('openEditor("Edit",0,false,true)');check(await evaluate('editor.taskFields.state.steps.length===4&&editor.taskFields.state.steps[0].text==="Edited step"&&editor.taskFields.state.steps.at(-1).text==="Saved pending step"'),'Edited/pending steps survive save/reopen');
  await hover('rows()[2]');await click('rows()[2].querySelector(".hub-task-step-remove")');check(await evaluate('rows().length===3'),'Pointer delete works');
  for(const touch of [true,false]){await call('Emulation.setTouchEmulationEnabled',{enabled:touch});await call('Emulation.setEmitTouchEventsForMouse',{enabled:touch,configuration:touch?'mobile':'desktop'});await evaluate('editor.taskFields.checklist.toggle.focus()');await move();const hover=await evaluate('matchMedia("(hover: hover) and (pointer: fine)").matches');check(await evaluate(`controlState(rows()[0]).every(c=>c.opacity==="${hover?'0':'1'}")`),'Capability-appropriate controls '+touch);if(touch){check(!hover,'Touch emulation exercises no-hover fallback');const n=await evaluate('rows().length'),p=await point('rows()[0].querySelector(".hub-task-step-remove")');await call('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[p]});await call('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await evaluate('frames()');check(await evaluate('rows().length')===n-1,'Touch delete accessible');}}
  await evaluate('editor.close();openEditor("Add",0)');await click('editor.taskFields.checklist.toggle');await evaluate('input(editor.taskFields.steps.draftInput,"Created Step")');await click('editor.contentEl.querySelector(".hub-task-dialog-actions .mod-cta")');check(await evaluate('editor.closed&&writeCount()===2'),'Add saves pending Step once');await evaluate('openEditor("Edit",0,false,true)');check(await evaluate('editor.taskFields.state.steps.length===1&&editor.taskFields.state.steps[0].text==="Created Step"'),'Add-created Step reopens');
  fs.writeFileSync(path.join(output,'result.json'),JSON.stringify({checks,status:'passed',host:'mocked Obsidian Modal/service with actual editor modules and native CSS'},null,2));console.log('PASS:',checks,'browser checks. Evidence:',output);
 }finally{clearTimeout(timeout);socket?.close();child.kill();await new Promise(r=>server.close(r))}
}
run().catch(error=>{console.error(error.stack);process.exitCode=1});
